@push('scripts')
<script>
function launchApplicantPayment(button,openerName){if(!button||button.disabled)return;var original=button.innerHTML;button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span> Opening…';try{var opener=typeof openerName==='string'?window[openerName]:openerName;if(typeof opener!=='function')throw new Error('The payment service is still loading.');opener()}catch(e){button.disabled=false;button.innerHTML=original;alert('Online payment is temporarily unavailable. Please try again later. Your payment has not been changed.');return}setTimeout(function(){button.disabled=false;button.innerHTML=original},1200)}
function paymentAction(form,message){var button=form.querySelector('button[type="submit"]');if(button){button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span> '+message}return true}
function confirmApplicantCancel(form){if(!window.confirm('Cancel this pending payment? You can start a new payment afterwards.'))return false;return paymentAction(form,'Cancelling…')}
function copyApplicantRrr(id){var node=document.getElementById('applicant-rrr-'+id);if(!node)return;var value=node.textContent.trim(),done=function(){alert('RRR copied: '+value)};if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(value).then(done).catch(function(){fallbackCopy(value,done)})}else fallbackCopy(value,done)}
function fallbackCopy(value,done){var input=document.createElement('textarea');input.value=value;input.style.position='fixed';input.style.opacity='0';document.body.appendChild(input);input.select();document.execCommand('copy');input.remove();done()}
</script>
@endpush
